    "sourceUrl": "https://www.izkor.gov.il/%D7%99%D7%9D%20%D7%92%D7%95%D7%9C%D7%93%D7%A9%D7%98%D7%99%D7%99%D7%9F%20%D7%90%D7%9C%D7%9E%D7%95%D7%92/en_9bfeee093a5ed4a33437bd87d34220e3",
